  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Valdecoxib, a sulfonamide-containing drug with very high assay transfer, has an absolute oral bioavailability of 83% in humans, directly supporting high F for the query's sulfonamide/aromatic system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Meloxicam, a sulfonamide enol carboxamide with high transferability, shows absolute oral bioavailability of 91% in healthy fasting volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Metolazone, a sulfonamide diuretic structurally related to the query's sulfamoyl benzamide, is approximately 100% bioavailable in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ixazomib, despite polar/ionizable groups, has an estimated absolute oral bioavailability of 60% in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Celecoxib, a poorly water-soluble sulfonamide, still achieves oral bioavailability of 20–40% in humans, meeting the F≥20% threshold and supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show oral bioavailability at or above 20%, mostly 38–100%, strongly supporting high F for the query molecule despite a mixed physicochemical prior.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "Physicochemical prior is mixed due to ionization and high TPSA, but experimental analogues with similar sulfonamide/aromatic features consistently show high F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

